mapper.sql:
WHERE l.deleted = FALSE

    AND (l.lecturer_name ILIKE #{q.keywordLike} ESCAPE '\'
      OR l.employee_no ILIKE #{q.keywordLike} ESCAPE '\'
      OR l.teaching_direction ILIKE #{q.keywordLike} ESCAPE '\')


    AND l.source_dept = #{q.sourceDept}



    AND l.expertise_domains @> to_jsonb(#{q.expertiseDomain}::TEXT)


    AND l.training_state = #{q.trainingState}


    AND l.trial_qualified = #{q.trialQualified}


    AND l.pool_state = #{q.poolState}


    AND l.join_type = #{q.joinType}


    AND l.joined_date >= #{q.joinedFrom}


    AND l.joined_date <= #{q.joinedTo}



    AND rating.avg_score >= #{q.scoreFrom}


    AND rating.avg_score <= #{q.scoreTo}
